package com.dronefleet.repository;
import com.dronefleet.domain.*;import java.sql.*;import java.util.*;
public final class DroneRepository { private final com.dronefleet.config.Database db; public DroneRepository(com.dronefleet.config.Database db){this.db=db;}
 public void save(Drone d){String q="INSERT INTO drones(id,type,capacity,battery,status,completed_deliveries,total_distance,total_revenue,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET type=excluded.type,capacity=excluded.capacity,battery=excluded.battery,status=excluded.status,completed_deliveries=excluded.completed_deliveries,total_distance=excluded.total_distance,total_revenue=excluded.total_revenue,updated_at=excluded.updated_at";try(Connection c=db.connect();PreparedStatement p=c.prepareStatement(q)){int i=1;p.setInt(i++,d.id());p.setString(i++,d.type());p.setDouble(i++,d.capacity());p.setInt(i++,d.battery());p.setString(i++,d.status().name());p.setInt(i++,d.completedDeliveries());p.setDouble(i++,d.totalDistance());p.setDouble(i++,d.totalRevenue());p.setString(i++,java.time.LocalDateTime.now().toString());p.setString(i,java.time.LocalDateTime.now().toString());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public Optional<Drone> find(int id){try(Connection c=db.connect();PreparedStatement p=c.prepareStatement("SELECT * FROM drones WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new RuntimeException(e);}}
 public List<Drone> findAll(){List<Drone> out=new ArrayList<>();try(Connection c=db.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM drones ORDER BY id")){while(r.next())out.add(map(r));}catch(SQLException e){throw new RuntimeException(e);}return out;}
 public void delete(int id){try(Connection c=db.connect();PreparedStatement p=c.prepareStatement("DELETE FROM drones WHERE id=?")){p.setInt(1,id);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 private Drone map(ResultSet r)throws SQLException{return new Drone(r.getInt("id"),r.getString("type"),r.getDouble("capacity"),r.getInt("battery"),DroneStatus.valueOf(r.getString("status")),r.getInt("completed_deliveries"),r.getDouble("total_distance"),r.getDouble("total_revenue"));}
}
